cmds.out:
server {
    listen 443 ssl;
    server_name pay-api.corp.example;
    ssl_certificate     /etc/nginx/tls/payroll.pem;
    ssl_certificate_key /etc/nginx/tls/payroll.key;
    ssl_protocols       TLSv1.2 TLSv1.3;
    location / { proxy_pass http://127.0.0.1:8080; }
}

# network.tf
provider "aws" {
  region = "us-gov-west-1"
}

resource "aws_security_group" "bastion" {
  name   = "bastion-sg"
  vpc_id = var.vpc_id

  ingress {
    description = "ssh"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

